from flask import Flask, render_template_string
import os
app = Flask(__name__)
PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hello World Motion Lab</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#172033;font-family:Arial,sans-serif}header{padding:22px 5vw 8px}header h1{margin:0 0 8px}header p{margin:0;color:#586174}main{display:grid;grid-template-columns:285px minmax(0,1fr);gap:20px;padding:18px 5vw 35px}.controls{background:white;border-radius:16px;padding:20px;box-shadow:0 5px 24px #17203312}label{display:block;font-weight:bold;font-size:14px;margin:14px 0 6px}input,select{width:100%;padding:10px;border:1px solid #cbd2df;border-radius:9px;font:inherit;background:white}input[type=range]{padding:0}output{font-weight:normal;color:#586174}.stage{position:relative;isolation:isolate;overflow:hidden;min-height:580px;height:min(72vh,700px);border-radius:18px;background:#f7f9fc;color:#172033;display:flex;align-items:center;justify-content:center;padding:30px;box-shadow:0 5px 24px #17203312}.effects{position:absolute;inset:0;z-index:1;overflow:hidden;pointer-events:none}.particle{position:absolute;top:-12%;user-select:none;opacity:.9;animation:fall var(--duration,6s) linear infinite}@keyframes fall{from{transform:translate3d(0,-10vh,0) rotate(0)}to{transform:translate3d(var(--drift),120vh,0) rotate(540deg)}}.stage.wind .particle{animation-name:gust}@keyframes gust{0%{transform:translate3d(-15vw,0,0);opacity:0}15%{opacity:.9}100%{transform:translate3d(120vw,35px,0) rotate(180deg);opacity:0}}.stage.tornado .particle{animation-name:swirl}@keyframes swirl{0%{transform:translate3d(-45px,620px,0) rotate(0) scale(.7)}50%{transform:translate3d(40px,250px,0) rotate(360deg) scale(1.25)}100%{transform:translate3d(-20px,-80px,0) rotate(720deg) scale(.7)}}.name-layer{position:relative;z-index:2;width:100%;text-align:center;font-weight:800;overflow-wrap:anywhere;text-shadow:0 2px 12px #0002}.ticker{width:100%;white-space:nowrap;overflow:hidden}.ticker span{display:inline-block;padding-left:100%;animation:marquee var(--marquee,12s) linear infinite}@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-100%)}}.repeated{line-height:1.5}.repeated div:nth-child(odd){transform:translateX(-3%)}.repeated div:nth-child(even){transform:translateX(3%)}.help{color:#586174;font-size:13px;line-height:1.5}@media(max-width:760px){main{grid-template-columns:1fr}.stage{min-height:430px;height:58vh}}
</style></head><body><header><h1>✨ Hello World Motion Lab</h1><p>Enter a name, customize its style, and experiment with looping motion.</p></header><main><section class="controls"><h2>Customize</h2><label for="nameInput">Enter your name</label><input id="nameInput" maxlength="80" value="Hello World"><label for="font">Font type</label><select id="font"><option>Arial</option><option>Courier New</option><option>Georgia</option><option>Times New Roman</option><option>Verdana</option><option>Trebuchet MS</option><option>Impact</option></select><label for="size">Font size: <output id="sizeValue">48 px</output></label><input id="size" type="range" min="20" max="100" step="2" value="48"><label for="background">Background</label><select id="background"><option>Light</option><option>Dark</option><option>Ocean</option><option>Sunset</option><option>Forest</option><option>Lavender</option></select><label for="mode">Name display mode</label><select id="mode"><option>Centered</option><option>Ticker Tape</option><option>Repeated</option></select><label for="effect">Dynamic action</label><select id="effect"><option>None</option><option>Rain</option><option>Snow</option><option>Hail</option><option>Wind Gust</option><option>Confetti</option><option>Tornado</option></select><label for="speed">Animation speed: <output id="speedValue">5</output></label><input id="speed" type="range" min="1" max="10" value="5"><p class="help">Animations loop in your browser. Your name is displayed as text.</p></section><section><div id="stage" class="stage"><div id="effects" class="effects" aria-hidden="true"></div><div id="nameLayer" class="name-layer">Hello World</div></div></section></main><script>
const $=id=>document.getElementById(id);const palettes={Light:['#f7f9fc','#172033'],Dark:['#10131a','#f7f7fb'],Ocean:['linear-gradient(135deg,#053b50,#176b87,#64ccc5)','#fff'],Sunset:['linear-gradient(135deg,#48205f,#d94f70,#ffb36b)','#fff'],Forest:['linear-gradient(135deg,#12372a,#436850,#adbc9f)','#fff'],Lavender:['linear-gradient(135deg,#eee5ff,#d9c7ff,#c4e0ff)','#282044']};const symbols={Rain:['💧','💦','⋮'],Snow:['❄','❅','❆','✻'],Hail:['🧊','○','●'],'Wind Gust':['〰','〜','💨','﹏'],Confetti:['🎉','🎊','✦','●','■','▲'],Tornado:['🌪','〰','﹏','·']};function rnd(a,b){return Math.random()*(b-a)+a}function render(){let stage=$('stage'),layer=$('nameLayer'),effects=$('effects'),name=$('nameInput').value||'Hello World',font=$('font').value,size=+$('size').value,bg=$('background').value,mode=$('mode').value,effect=$('effect').value,speed=+$('speed').value,duration=11-speed;let [colorBg,colorText]=palettes[bg];stage.style.background=colorBg;stage.style.color=colorText;stage.className='stage';if(effect==='Wind Gust')stage.classList.add('wind');if(effect==='Tornado')stage.classList.add('tornado');layer.style.fontFamily="'"+font.replaceAll("'",'')+"',sans-serif";layer.style.fontSize=size+'px';layer.replaceChildren();if(mode==='Ticker Tape'){let d=document.createElement('div'),s=document.createElement('span');d.className='ticker';s.textContent=name+'   ✨   '+name+'   ✨   ';s.style.setProperty('--marquee',Math.max(4,duration*1.8)+'s');d.appendChild(s);layer.appendChild(d)}else if(mode==='Repeated'){let d=document.createElement('div');d.className='repeated';d.style.fontSize=Math.max(18,size*.62)+'px';for(let i=0;i<6;i++){let line=document.createElement('div');line.textContent=name;d.appendChild(line)}layer.appendChild(d)}else layer.textContent=name;$('sizeValue').textContent=size+' px';$('speedValue').textContent=speed;effects.replaceChildren();if(effect!=='None'){let count=['Rain','Snow','Hail','Confetti'].includes(effect)?44:24;for(let i=0;i<count;i++){let p=document.createElement('span');p.className='particle';p.textContent=symbols[effect][Math.floor(Math.random()*symbols[effect].length)];p.style.left=rnd(0,100)+'%';p.style.fontSize=rnd(12,28)+'px';p.style.setProperty('--drift',rnd(-100,100)+'px');p.style.setProperty('--duration',Math.max(2,duration*(effect==='Wind Gust'?.7:effect==='Tornado'?.75:1))+'s');p.style.animationDelay=-rnd(0,duration)+'s';effects.appendChild(p)}}}['nameInput','font','size','background','mode','effect','speed'].forEach(id=>$(id).addEventListener('input',render));render();
</script></body></html>'''

@app.route('/')
def home():
    return render_template_string(PAGE)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 10000)))
